CREATE TABLE settings(version INTEGER PRIMARY KEY,body TEXT NOT NULL CHECK(json_valid(body)),created INTEGER NOT NULL,actor TEXT NOT NULL);
CREATE TABLE users(id TEXT PRIMARY KEY,name TEXT NOT NULL UNIQUE,display_name TEXT NOT NULL,salt TEXT NOT NULL,hash TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN ('admin','employee')),active INTEGER NOT NULL DEFAULT 1 CHECK(active IN (0,1)),identity TEXT NOT NULL,totp_box TEXT,totp_step INTEGER NOT NULL DEFAULT -1,revision INTEGER NOT NULL DEFAULT 0);
CREATE INDEX user_identity ON users(identity);
CREATE TABLE sessions(token TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),identity TEXT NOT NULL,csrf TEXT NOT NULL,expires INTEGER NOT NULL,user_revision INTEGER NOT NULL);
CREATE INDEX session_expiry ON sessions(expires);
CREATE TABLE attempts(bucket TEXT PRIMARY KEY,count INTEGER NOT NULL,until_at INTEGER NOT NULL);
CREATE TABLE cards(id INTEGER PRIMARY KEY CHECK(id BETWEEN 1 AND 60),token_hash TEXT NOT NULL UNIQUE,token_box TEXT NOT NULL,state TEXT NOT NULL CHECK(state IN ('available','assigned','reserve','suspended','lost','revoked')),revision INTEGER NOT NULL DEFAULT 0);
CREATE TABLE stays(id TEXT PRIMARY KEY,card_id INTEGER NOT NULL REFERENCES cards(id),vehicle TEXT NOT NULL CHECK(json_valid(vehicle)),service TEXT NOT NULL CHECK(json_valid(service)),entered INTEGER NOT NULL,actor TEXT NOT NULL,state TEXT NOT NULL CHECK(state IN ('active','closed','cancelled')),exited INTEGER,revision INTEGER NOT NULL DEFAULT 0);
CREATE UNIQUE INDEX one_active_card ON stays(card_id) WHERE state='active';
CREATE INDEX stays_state_time ON stays(state,entered);
CREATE INDEX stays_exited ON stays(state,exited);
CREATE TRIGGER enforce_capacity BEFORE INSERT ON stays WHEN NEW.state='active' BEGIN SELECT CASE WHEN (SELECT count(*) FROM stays WHERE state='active')>=30 THEN RAISE(ABORT,'OESTE_CAPACITY') END; END;
CREATE TABLE monthly(id TEXT PRIMARY KEY,mode TEXT NOT NULL CHECK(json_valid(mode)),start_at INTEGER NOT NULL,end_at INTEGER NOT NULL,vehicle TEXT NOT NULL CHECK(json_valid(vehicle)),actor TEXT NOT NULL,created INTEGER NOT NULL,revision INTEGER NOT NULL DEFAULT 0,CHECK(end_at>start_at));
CREATE INDEX monthly_end ON monthly(end_at);
CREATE TABLE payments(id TEXT PRIMARY KEY,stay_id TEXT UNIQUE REFERENCES stays(id),monthly_id TEXT UNIQUE REFERENCES monthly(id),lines TEXT NOT NULL CHECK(json_valid(lines)),total INTEGER NOT NULL CHECK(typeof(total)='integer' AND total>=0 AND total<=100000000),actor TEXT NOT NULL,paid INTEGER NOT NULL,CHECK(stay_id IS NOT NULL OR monthly_id IS NOT NULL));
CREATE INDEX payments_time ON payments(paid);
CREATE INDEX payments_actor_time ON payments(actor,paid);
CREATE TRIGGER immutable_payment_update BEFORE UPDATE ON payments BEGIN SELECT RAISE(ABORT,'OESTE_IMMUTABLE_PAYMENT'); END;
CREATE TRIGGER immutable_payment_delete BEFORE DELETE ON payments BEGIN SELECT RAISE(ABORT,'OESTE_IMMUTABLE_PAYMENT'); END;
CREATE TABLE operations(id TEXT PRIMARY KEY,user_id TEXT NOT NULL,request_key TEXT NOT NULL,fingerprint TEXT NOT NULL,kind TEXT NOT NULL,result_box TEXT NOT NULL,at INTEGER NOT NULL,UNIQUE(user_id,request_key));
CREATE INDEX operation_time ON operations(at);
CREATE TABLE tx_guard(operation_id TEXT PRIMARY KEY REFERENCES operations(id),ok INTEGER NOT NULL CHECK(ok=1));
CREATE TABLE backup_chunks(operation_id TEXT NOT NULL REFERENCES operations(id),chunk_index INTEGER NOT NULL,data TEXT NOT NULL,PRIMARY KEY(operation_id,chunk_index));
CREATE TABLE audit(id INTEGER PRIMARY KEY AUTOINCREMENT,at INTEGER NOT NULL,actor TEXT NOT NULL,action TEXT NOT NULL,entity TEXT NOT NULL,detail TEXT NOT NULL CHECK(json_valid(detail)));
CREATE INDEX audit_time ON audit(at);
CREATE TABLE meta(id TEXT PRIMARY KEY,value TEXT NOT NULL);
